CREATE DATABASE IF NOT EXISTS leader_app CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE leader_app;
CREATE TABLE IF NOT EXISTS shops(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS branches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shop_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_branch(shop_id,name),UNIQUE KEY uq_branch_scope(id,shop_id),FOREIGN KEY(shop_id) REFERENCES shops(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shop_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NULL,email VARCHAR(254) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('employee','branch_manager','company_manager','owner') NOT NULL DEFAULT 'employee',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_email(email),FOREIGN KEY(shop_id) REFERENCES shops(id) ON DELETE CASCADE,FOREIGN KEY(branch_id,shop_id) REFERENCES branches(id,shop_id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shop_id BIGINT UNSIGNED NOT NULL,item_code VARCHAR(80) NOT NULL,name VARCHAR(160) NOT NULL,category VARCHAR(120) NOT NULL DEFAULT '',unit VARCHAR(30) NOT NULL DEFAULT 'قطعة',quantity DECIMAL(12,2) NOT NULL DEFAULT 0,min_quantity DECIMAL(12,2) NOT NULL DEFAULT 0,cost_price DECIMAL(12,2) NOT NULL DEFAULT 0,sell_price DECIMAL(12,2) NOT NULL DEFAULT 0,expiry_date DATE NULL,UNIQUE KEY uq_product(shop_id,item_code),UNIQUE KEY uq_product_scope(id,shop_id),FOREIGN KEY(shop_id) REFERENCES shops(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS exports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,shop_id BIGINT UNSIGNED NOT NULL,branch_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(12,2) NOT NULL,export_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(shop_id) REFERENCES shops(id) ON DELETE CASCADE,FOREIGN KEY(branch_id,shop_id) REFERENCES branches(id,shop_id),FOREIGN KEY(product_id,shop_id) REFERENCES products(id,shop_id)) ENGINE=InnoDB;

